class HealthPassportPage extends StatefulWidget { const HealthPassportPage({super.key}); @override State<HealthPassportPage> createState()=>_HealthPassportPageState(); }
class _HealthPassportPageState extends State<HealthPassportPage>{ bool sharing=false; @override Widget build(BuildContext c){final l=AppLocalizations.of(c);return Scaffold(appBar:AppBar(title:Text(l.passportTitle),actions:[IconButton(onPressed:(){Clipboard.setData(ClipboardData(text:'MediBook-PASSPORT-2026'));ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text(l.passportCopied)));},icon:const Icon(Icons.copy_outlined))]),body:ListView(padding:const EdgeInsetsDirectional.all(20),children:[Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(borderRadius:BorderRadius.circular(28),gradient:const LinearGradient(colors:[Color(0xff163B5C),Color(0xff49B7A8])),),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[const Icon(Icons.verified_user_outlined,color:Colors.white,size:30),const Spacer(),Text(l.passportPrivate,style:const TextStyle(color:Colors.white70))]),const SizedBox(height:20),Text(l.passportName,style:const TextStyle(color:Colors.white,fontSize:24,fontWeight:FontWeight.w800)),const SizedBox(height:6),Text(l.passportSummary,style:const TextStyle(color:Colors.white70)),const SizedBox(height:22),Row(children:[_Stat(label:l.passportBloodType,value:'O+'),_Stat(label:l.passportAllergies,value:'1'),_Stat(label:l.passportConditions,value:'2')])])),const SizedBox(height:16),Card(child:SwitchListTile(value:sharing,onChanged:(v)=>setState(()=>sharing=v),title:Text(l.passportSharing),subtitle:Text(sharing?l.passportSharingOn:l.passportSharingOff),secondary:const Icon(Icons.share_outlined))),Card(child:ListTile(leading:const Icon(Icons.warning_amber_outlined),title:Text(l.passportEmergency),subtitle:Text(l.passportEmergencyValue))),Card(child:ListTile(leading:const Icon(Icons.lock_outline),title:Text(l.passportConsent),subtitle:Text(l.passportConsentValue))),const SizedBox(height:12),Text(l.passportFooter,style:Theme.of(c).textTheme.bodySmall)]);}}
class _Stat extends StatelessWidget { const _Stat({required this.label,required this.value}); final String label,value; @override Widget build(BuildContext c)=>Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(value,style:const TextStyle(color:Colors.white,fontSize:20,fontWeight:FontWeight.bold)),Text(label,style:const TextStyle(color:Colors.white70))]));}
